import { useMemo } from 'react'
import { isPinned, type Place, type PinnedPlace } from '../types/places'

// Static import — places.json is generated by scripts/processGeodata.ts
import placesData from '../data/places.json'

// The map can only show places with a known site; unpinned ones carry a locationNote instead.
const allPlaces: PinnedPlace[] = (placesData as Place[]).filter(isPinned)

export function useParshaPlaces(parshaId: string | null): PinnedPlace[] {
  return useMemo(() => {
    if (!parshaId) return []
    return allPlaces.filter((p) => p.parshas.includes(parshaId))
  }, [parshaId])
}
